import { describe, expect, it } from 'vitest';
import * as fc from 'fast-check';
import {
  canonicalize,
  decodeRecord,
  encodeRecord,
} from '../src/query-record';

// Scalar values exclude UTF-16 surrogate code points.
const scalar = fc.oneof(
  fc.integer({ min: 0, max: 0xd7ff }),
  fc.integer({ min: 0xe000, max: 0x10ffff }),
).map((n) => String.fromCodePoint(n));

const text = fc.oneof(
  fc.array(scalar, { maxLength: 32 }).map((xs) => xs.join('')),
  fc.constantFrom(
    '', '&', '=', '%', '+', '\0', 'é', 'e\u0301',
    '\uE000', '\u{10000}', '__proto__', 'constructor',
  ),
);

const entries = fc.uniqueArray(fc.tuple(text, text), {
  selector: ([key]) => key,
  maxLength: 12,
});

const record = entries.map((pairs) => Object.fromEntries(pairs));

// Construct valid wire text independently of the production encoder.
// Full escaping also exercises non-canonical escapes of unreserved characters.
function component(value: string, literal: boolean, lower: boolean): string {
  return Array.from(value, (character) => {
    if (literal && /^[A-Za-z0-9._~-]$/.test(character)) return character;
    return Array.from(new TextEncoder().encode(character), (byte) => {
      const hex = byte.toString(16).padStart(2, '0');
      return `%${lower ? hex : hex.toUpperCase()}`;
    }).join('');
  }).join('');
}

const validWire = fc.tuple(
  entries, fc.boolean(), fc.boolean(),
).map(([pairs, literal, lower]) => ({
  expected: Object.fromEntries(pairs),
  wire: pairs.map(([key, value]) =>
    `${component(key, literal, lower)}=${component(value, literal, !lower)}`
  ).join('&'),
}));

const brokenEscape = fc.oneof(
  fc.constantFrom('%', '%0'),
  fc.tuple(
    fc.constantFrom('G', 'g', '-', '_', 'z'),
    fc.integer({ min: 0, max: 15 }),
    fc.boolean(),
  ).map(([bad, digit, first]) =>
    first ? `%${bad}${digit.toString(16)}` : `%${digit.toString(16)}${bad}`
  ),
);

const invalidUtf8 = fc.oneof(
  // Continuation bytes without a leading byte.
  fc.integer({ min: 0x80, max: 0xbf })
    .map((byte) => `%${byte.toString(16)}`),
  // Leading bytes without their required continuation byte.
  fc.integer({ min: 0xc2, max: 0xdf })
    .map((byte) => `%${byte.toString(16)}`),
  fc.constantFrom(
    '%C0%AF',       // Overlong encoding.
    '%ED%A0%80',    // Encoded surrogate.
    '%F4%90%80%80', // Above the Unicode maximum.
    '%FF',         // Invalid leading byte.
  ),
);

function inEitherComponent(bad: fc.Arbitrary<string>) {
  return fc.tuple(text, bad, fc.boolean()).map(([valid, invalid, key]) => {
    const safe = component(valid, false, false);
    return key ? `${safe}${invalid}=x` : `x=${safe}${invalid}`;
  });
}

const malformed: Array<[string, fc.Arbitrary<string>]> = [
  [
    'segments without a separator',
    text.map((key) => `ok=x&${component(key, false, false)}`),
  ],
  [
    'duplicate decoded keys',
    fc.tuple(text, text, text).map(([key, first, second]) =>
      `${component(key, true, false)}=${component(first, false, false)}&` +
      `${component(key, false, true)}=${component(second, false, true)}`
    ),
  ],
  ['malformed percent escapes', inEitherComponent(brokenEscape)],
  ['invalid UTF-8', inEitherComponent(invalidUtf8)],
];

const seeds = [20260919, 1729];

function check<T>(arbitrary: fc.Arbitrary<T>, assertion: (value: T) => void) {
  for (const seed of seeds) {
    fc.assert(fc.property(arbitrary, assertion), {
      seed,
      numRuns: 200,
      interruptAfterTimeLimit: 2000,
      markInterruptAsFailure: true,
    });
  }
}

describe('query record contract', () => {
  // Tracer bullet: every generated pair crosses the UTF-16 ordering boundary.
  it('orders BMP keys before supplementary keys by code point', () => {
    check(
      fc.tuple(
        fc.integer({ min: 0xe000, max: 0xffff }),
        fc.integer({ min: 0x10000, max: 0x10ffff }),
        text,
      ),
      ([bmp, supplementary, value]) => {
        const first = String.fromCodePoint(bmp);
        const second = String.fromCodePoint(supplementary);
        const wire = encodeRecord({ [second]: value, [first]: value });
        const keys = wire.split('&').map((segment) =>
          decodeURIComponent(segment.slice(0, segment.indexOf('=')))
        );
        expect(keys).toEqual([first, second]);
      },
    );
  });

  it('preserves the smallest cross-plane ordering regression', () => {
    expect(encodeRecord({ '\u{10000}': '', '\uE000': '' }))
      .toBe('%EE%80%80=&%F0%90%80%80=');
  });

  it('preserves logical records through encoding and decoding', () => {
    check(record, (value) => {
      expect(decodeRecord(encodeRecord(value))).toEqual(value);
    });
  });

  it('decodes valid representations and canonicalizes consistently', () => {
    check(validWire, ({ wire, expected }) => {
      expect(decodeRecord(wire)).toEqual(expected);
      const canonical = canonicalize(wire);
      expect(canonical).toBe(encodeRecord(expected));
      expect(decodeRecord(canonical)).toEqual(expected);
      expect(canonicalize(canonical)).toBe(canonical);
    });
  });

  it('handles empty records and empty components', () => {
    expect(encodeRecord({})).toBe('');
    expect(decodeRecord('')).toEqual({});
    expect(canonicalize('')).toBe('');
    expect(encodeRecord({ '': '' })).toBe('=');
    expect(decodeRecord('=')).toEqual({ '': '' });
  });

  for (const [reason, arbitrary] of malformed) {
    it(`rejects ${reason}`, () => {
      check(arbitrary, (wire) => {
        expect(() => decodeRecord(wire)).toThrow();
        expect(() => canonicalize(wire)).toThrow();
      });
    });
  }
});
