import * as fc from 'fast-check';
import { encodeRecord } from '../src/query-record';

// Surrogates are not Unicode scalar values.
const scalar = fc.oneof(
  fc.integer({ min: 0, max: 0xd7ff }),
  fc.integer({ min: 0xe000, max: 0xffff }),
  fc.integer({ min: 0x10000, max: 0x10ffff }),
).map((point) => String.fromCodePoint(point));

const scalarString = fc.oneof(
  fc.array(scalar, { maxLength: 24 }).map((chars) => chars.join('')),
  fc.constantFrom(
    '',
    '&',
    '=',
    '%',
    '\0',
    '\u007f',
    '\u0080',
    '\ud7ff',
    '\ue000',
    '\uffff',
    '\u{10000}',
    '\u{10ffff}',
    'é',
    'e\u0301',
    '__proto__',
    'constructor',
  ),
);

const entries = fc.uniqueArray(
  fc.tuple(scalarString, scalarString),
  { selector: ([key]) => key, maxLength: 16 },
);

// Fixed-width scalar numbers give an independent lexical ordering oracle.
// Iteration is by code point, including supplementary-plane characters.
function scalarOrderKey(value: string): string {
  return Array.from(value, (char) =>
    char.codePointAt(0)!.toString(16).padStart(6, '0'),
  ).join('');
}

it('emits query-record keys in Unicode code-point order', () => {
  fc.assert(
    fc.property(entries, (pairs) => {
      const record = Object.fromEntries(pairs);
      const wire = encodeRecord(record);
      const actualKeys = wire === ''
        ? []
        : wire.split('&').map((segment) =>
            decodeURIComponent(segment.slice(0, segment.indexOf('='))),
          );

      const expectedKeys = pairs.map(([key]) => key).sort((left, right) => {
        const a = scalarOrderKey(left);
        const b = scalarOrderKey(right);
        return a < b ? -1 : a > b ? 1 : 0;
      });

      expect(actualKeys).toEqual(expectedKeys);
    }),
    {
      numRuns: 300,
      seed: 20260919,
      verbose: true,
      examples: [
        [[]],
        [[['', '']]],
        [[['a', '1'], ['b', '2']]],
        [[['\u{10000}', ''], ['\ue000', '']]],
        [[['&=%', '\0'], ['__proto__', 'é']]],
      ],
    },
  );
}, 10_000);
```

