import { describe, expect, it } from 'vitest';
import * as fc from 'fast-check';
import { canonicalize, decodeRecord, encodeRecord } from '../src/query-record';

const options = {
  seed: 20260919,
  numRuns: 300,
  // Disable Vitest's wall-clock deadline below; bound generated sizes here.
};

const scalar = fc.oneof(
  fc.integer({ min: 0, max: 0xd7ff }),
  fc.integer({ min: 0xe000, max: 0x10ffff }),
).map((point) => String.fromCodePoint(point));

const text = fc.oneof(
  fc.stringOf(scalar, { maxLength: 20 }),
  fc.constantFrom(
    '', '&', '=', '%', '+', '\0', 'é', 'e\u0301',
    '\uE000', '\u{10000}', '__proto__', 'constructor',
  ),
);

const entries = fc.uniqueArray(fc.tuple(text, text), {
  selector: ([key]) => key,
  maxLength: 12,
});

// Alternate spelling: percent-encode every UTF-8 byte, including ASCII.
function escaped(value: string, lower: boolean): string {
  return Array.from(new TextEncoder().encode(value), (byte) => {
    const hex = byte.toString(16).padStart(2, '0');
    return `%${lower ? hex : hex.toUpperCase()}`;
  }).join('');
}

// Independent ordering oracle: compare sequences of numeric scalar values.
function compareKeys(left: string, right: string): number {
  const a = Array.from(left, (char) => char.codePointAt(0)!);
  const b = Array.from(right, (char) => char.codePointAt(0)!);
  for (let i = 0; i < Math.min(a.length, b.length); i++) {
    if (a[i] !== b[i]) return a[i] - b[i];
  }
  return a.length - b.length;
}

const validWire = fc.tuple(entries, fc.boolean(), fc.boolean()).map(
  ([pairs, lower, allEscaped]) => {
    const encode = (value: string) =>
      allEscaped ? escaped(value, lower) : encodeURIComponent(value);
    return {
      record: Object.fromEntries(pairs),
      wire: pairs.map(([key, value]) =>
        `${encode(key)}=${encode(value)}`).join('&'),
    };
  },
);

const malformedWire = fc.oneof(
  // No equals sign, even when the logical text contains one.
  text.map((value) => `x${encodeURIComponent(value)}`),
  // Different spellings of the same decoded key.
  fc.tuple(text, text).map(([key, value]) =>
    `${encodeURIComponent(key)}=${encodeURIComponent(value)}&` +
    `${escaped(key, true)}=`,
  ),
  fc.tuple(
    fc.constantFrom('%', '%0', '%GG', '%0G', '%G0'),
    fc.boolean(),
  ).map(([bad, inKey]) => inKey ? `${bad}=x` : `x=${bad}`),
  fc.tuple(
    fc.oneof(
      // A continuation byte cannot start a UTF-8 sequence.
      fc.integer({ min: 0x80, max: 0xbf })
        .map((byte) => `%${byte.toString(16)}`),
      fc.constantFrom(
        '%C0%AF', '%C2', '%E2%82', '%ED%A0%80',
        '%F4%90%80%80', '%FF',
      ),
    ),
    fc.boolean(),
  ).map(([bad, inKey]) => inKey ? `${bad}=x` : `x=${bad}`),
);

describe('query-record contract properties', () => {
  it('preserves every generated logical record', () => {
    fc.assert(fc.property(entries, (pairs) => {
      const record = Object.fromEntries(pairs);
      expect(decodeRecord(encodeRecord(record))).toEqual(record);
    }), options);
  }, 0);

  it('encodes keys in scalar order with canonical escaping', () => {
    fc.assert(fc.property(entries, (pairs) => {
      const expected = [...pairs]
        .sort(([a], [b]) => compareKeys(a, b))
        .map(([key, value]) =>
          `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
        .join('&');
      expect(encodeRecord(Object.fromEntries(pairs))).toBe(expected);
    }), options);
  }, 0);

  it('preserves valid wire meaning and canonicalizes idempotently', () => {
    fc.assert(fc.property(validWire, ({ record, wire }) => {
      expect(decodeRecord(wire)).toEqual(record);
      const canonical = canonicalize(wire);
      expect(canonical).toBe(encodeRecord(record));
      expect(decodeRecord(canonical)).toEqual(record);
      expect(canonicalize(canonical)).toBe(canonical);
    }), options);
  }, 0);

  it('rejects malformed wire through both accepting interfaces', () => {
    fc.assert(fc.property(malformedWire, (wire) => {
      expect(() => decodeRecord(wire)).toThrow();
      expect(() => canonicalize(wire)).toThrow();
    }), options);
  }, 0);

  it('encodes the empty record as the empty wire', () => {
    expect(encodeRecord({})).toBe('');
    expect(decodeRecord('')).toEqual({});
  });

  it('orders U+E000 before U+10000', () => {
    expect(encodeRecord({ '\uE000': '', '\u{10000}': '' }))
      .toBe('%EE%80%80=&%F0%90%80%80=');
  });
});
```

